INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "福原綾香", "O", 3, "ヒューマン", "人々を守るために歌う、唱喚士の少女", "各種楽器", "チカ（クリスマス）", 46, "カルミナ", 4, 17, 0, 6, 108401, 163);
INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES ("あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "植田佳奈", "B", 9, "ヒューマン", "泣き虫で臆病な守ってあげたい女の子", "観劇、おままごと", "クルミ（クリスマス）", 40, "サレンディア救護院", 9, 12, 0, 6, 108501, 150);
